"""Side-by-side summary of the 2026-09-20 (archived) and 2026-11-05 hop FEA records, with similarity checks.

Reads only compiled JSON records; writes results/three_link_designs_<GRAVCOMM_FEA_TAG>/hop_vs_archived_summary.json.
"""
import json,math,os
from pathlib import Path
import numpy as np
ROOT=Path(__file__).resolve().parent
R=ROOT/'results'
TAG=os.environ.get('GRAVCOMM_FEA_TAG','2026_11_05_nb')
SETS=dict(archived=dict(steel=R/'three_link_designs_2026_09_20',w=R/'tungsten_comparison_2026_09_20',half=3*.08/(.4*(224/162)),T=.6*224/162),
          hop=dict(steel=R/f'three_link_designs_{TAG}',w=R/f'tungsten_comparison_{TAG}',half=0.545306,T=224/190))
STEEL_INSERT_H0_MM=79.24044075275058
def rd(p):return json.loads(p.read_text())
def modal(rows,i,h=.013):
 c=next(x for x in rows if x['design']==i and x['mesh']==h and x['speed']=='center');j=int(np.argmax(c['angular_effective_inertia_fraction']))
 out=dict(center_first3_hz=c['frequencies_hz'][:3],torsional_mode=j+1,torsional_hz=c['frequencies_hz'][j],torsional_eta=c['angular_effective_inertia_fraction'][j],
  translation_fraction_first3=[float(sum(v[k] for v in c['translation_effective_mass_fraction'])) for k in range(3)])
 for sp in ('low','high'):
  r=next((x for x in rows if x['design']==i and x['mesh']==h and x['speed']==sp),None)
  if r is None:continue
  k=r['matched_center_modes'][j]-1;out[f'{sp}_matched_torsional_mode']=k+1;out[f'{sp}_matched_torsional_hz']=r['frequencies_hz'][k];out[f'{sp}_matched_torsional_mac']=r['matched_mac'][j];out[f'{sp}_matched_torsional_eta']=r['angular_effective_inertia_fraction'][k]
  out[f'{sp}_first3_hz']=r['frequencies_hz'][:3];out[f'{sp}_min_mac']=min(r['matched_mac']);out[f'{sp}_matched_first3_hz']=[r['frequencies_hz'][r['matched_center_modes'][q]-1] for q in range(3)];out[f'{sp}_identity_matching']=r['matched_center_modes']==list(range(1,13))
 d=c['forced_response_diagnostics']
 out['isolated_transition_max_peak_over_static']={str(q['damping_ratio']):max(q['isolated_transition_modal_peak_over_static_peak']) for q in d}
 out['isolated_transition_torsional_peak_over_static']={str(q['damping_ratio']):q['isolated_transition_modal_peak_over_static_peak'][j] for q in d}
 out['gravity_rotation_amplification_mode1']={str(q['damping_ratio']):q['gravity_rotation_modal_amplification'][0] for q in d}
 out['gravity_rotation_amplification_max']={str(q['damping_ratio']):max(q['gravity_rotation_modal_amplification']) for q in d}
 return out
MARK='<!-- side-by-side comparison generated by summarize_hop_vs_archived.py -->'
def write_markdown(out):
 A,B=out['archived']['rows'],out['hop']['rows'];L=[MARK,'',f'## Side-by-side: archived 2026-09-20 vs {TAG} (fine 13 mm mesh unless stated)','',
  'Each cell is archived / new. Combined bounds are the horizontal-shaft triangle-inequality bounds of Appendix A.','']
 def row(label,get,fmt='{:.2f}'):
  L.append(f'| {label} | '+' | '.join(f'{fmt.format(get(a))} / {fmt.format(get(b))}' for a,b in zip(A,B))+' |')
 L.extend(['| Quantity | 0.5 m | 1 m | 2 m |','|:---|---:|---:|---:|'])
 row('Scale s',lambda x:x['scale'],'{:.6f}');row('Carrier f_g (Hz)',lambda x:x['carrier_hz'],'{:g}')
 row('Max rotation (rpm)',lambda x:x['omega_max_rad_s']*30/math.pi,'{:.3f}');row('Peak alpha (rad/s^2)',lambda x:x['alpha_max_rad_s2'],'{:.4f}')
 row('CAD mass (kg)',lambda x:x['cad_mass_kg'],'{:.4f}');row('CAD polar inertia (kg m^2)',lambda x:x['cad_inertia_kg_m2'],'{:.5f}');row('Peak rigid torque (N m)',lambda x:x['peak_torque_nm'],'{:.4f}')
 row('Fine-mesh mass (kg)',lambda x:x['mesh_mass_kg_fine'],'{:.4f}')
 g=lambda k:(lambda x:x['steel'][k])
 row('Centrifugal Al peak, fine (MPa)',g('centrifugal_alu_peak_mpa'));row('Centrifugal Al peak, coarse (MPa)',g('centrifugal_alu_peak_coarse_mpa'))
 row('Horizontal combined Al bound (MPa)',g('horizontal_combined_alu_bound_mpa'));row('Centrifugal displacement (um)',g('centrifugal_u_um'))
 row('Horizontal combined displacement bound (um)',g('horizontal_combined_u_bound_um'));row('Angular-acceleration-only Al peak (MPa)',g('angular_only_alu_mpa'),'{:.4f}')
 row('In-plane gravity Al bound (MPa)',g('horizontal_gravity_alu_bound_mpa'),'{:.4f}');row('All-attitude combined Al bound (MPa)',g('all_attitude_alu_bound_mpa'))
 row('All-attitude combined displacement bound (um)',g('all_attitude_u_bound_um'));row('Phase-sampled transition Al bound, any attitude (MPa)',g('phase_sampled_alu_bound_mpa'))
 row('All-attitude steel-insert bound (MPa)',g('all_attitude_insert_bound_mpa'))
 row('Regional 10 mm-ref. combined average, fine (MPa)',g('regional_10mm_fine_mpa'),'{:.3f}');row('Regional 10 mm-ref. combined average, coarse (MPa)',g('regional_10mm_coarse_mpa'),'{:.3f}')
 row('Mesh change, raw centrifugal Al peak (%)',g('raw_peak_change_percent'));row('Mesh change, max displacement (%)',g('displacement_change_percent'),'{:.3f}')
 row('Mesh change, regional combined average (%)',g('regional_change_percent'),'{:.3f}')
 m=lambda f:(lambda x:f(x['steel']['modes']))
 L.append('| Center-speed first three modes (Hz) | '+' | '.join(', '.join(f'{v:.2f}' for v in a['steel']['modes']['center_first3_hz'])+' / '+', '.join(f'{v:.2f}' for v in b['steel']['modes']['center_first3_hz']) for a,b in zip(A,B))+' |')
 row('Torsional (max angular-coupling) mode no.',m(lambda q:q['torsional_mode']),'{:d}');row('Torsional mode, center (Hz)',m(lambda q:q['torsional_hz']));row('Torsional effective polar-inertia fraction (%)',m(lambda q:100*q['torsional_eta']))
 row('Torsional mode, low speed, MAC-matched (Hz)',m(lambda q:q['low_matched_torsional_hz']),'{:.3f}');row('Torsional mode, high speed, MAC-matched (Hz)',m(lambda q:q['high_matched_torsional_hz']),'{:.3f}')
 row('Min MAC low/high vs center (all 12 modes)',m(lambda q:min(q['low_min_mac'],q['high_min_mac'])),'{:.6f}')
 row('Transition duration T (s)',g('transition_s'),'{:.6f}');row('First-mode period (ms)',lambda x:1e3*x['steel']['first_mode_period_s'],'{:.2f}');row('Torsional period (ms)',lambda x:1e3*x['steel']['torsional_period_s'],'{:.2f}')
 row('T / first-mode period',g('transition_over_first_period'),'{:.1f}');row('T / torsional period',g('transition_over_torsional_period'),'{:.1f}')
 for z in ('0.005','0.02','0.05'):row(f'Isolated transition max modal peak/static, zeta={z}',m(lambda q,z=z:q['isolated_transition_max_peak_over_static'][z]),'{:.6f}')
 row('Gravity-rotation amplification, mode 1, zeta=0.02',m(lambda q:q['gravity_rotation_amplification_mode1']['0.02']),'{:.4f}')
 row('Shaft-only torsion screen (Hz)',g('shaft_only_torsion_hz'));row('Shaft/carrier series torsion screen (Hz)',g('series_shaft_carrier_torsion_hz'))
 w=lambda k:(lambda x:x['tungsten'][k])
 L.extend(['','### Same-mass tungsten inserts','','| Quantity | 0.5 m | 1 m | 2 m |','|:---|---:|---:|---:|'])
 row('Horizontal Al bound, steel (MPa)',w('steel_horizontal_alu_bound_mpa'));row('Horizontal Al bound, tungsten (MPa)',w('horizontal_combined_alu_bound_mpa'))
 row('Horizontal displacement bound, steel (um)',w('steel_horizontal_u_bound_um'));row('Horizontal displacement bound, tungsten (um)',w('horizontal_combined_u_bound_um'))
 row('All-attitude insert bound, steel (MPa)',w('all_attitude_insert_bound_steel_mpa'));row('All-attitude insert bound, tungsten (MPa)',w('all_attitude_insert_bound_tungsten_mpa'))
 row('W centrifugal Al peak, coarse (MPa)',w('centrifugal_alu_peak_coarse_mpa'));row('W centrifugal Al peak, fine (MPa)',w('centrifugal_alu_peak_fine_mpa'))
 row('W mesh change, displacement (%)',w('displacement_change_percent'),'{:.3f}');row('W mesh change, regional (%)',w('regional_change_percent'),'{:.3f}')
 L.append('| W center-speed first three modes (Hz) | '+' | '.join(', '.join(f'{v:.2f}' for v in a['tungsten']['modes']['center_first3_hz'])+' / '+', '.join(f'{v:.2f}' for v in b['tungsten']['modes']['center_first3_hz']) for a,b in zip(A,B))+' |')
 row('W torsional mode (Hz)',lambda x:x['tungsten']['modes']['torsional_hz']);row('W torsional inertia fraction (%)',lambda x:100*x['tungsten']['modes']['torsional_eta'])
 row('Steel insert length (mm)',w('steel_insert_length_mm'));row('Tungsten insert length (mm)',w('tungsten_insert_length_mm'))
 row('Steel second harmonic (1e-10 m/s^2)',lambda x:1e10*x['tungsten']['field']['steel_a2_m_s2'],'{:.5f}');row('Tungsten second harmonic (1e-10 m/s^2)',lambda x:1e10*x['tungsten']['field']['tungsten_a2_m_s2'],'{:.5f}')
 row('Tungsten signal change (%)',lambda x:x['tungsten']['field']['relative_signal_change_percent'],'{:.3f}')
 for k,lab in (('archived','archived'),('hop',TAG)):
  r=out[k]['tungsten_refinement'];L.append(f"\nTungsten 10 mm third mesh ({lab}, 0.5 m rotor, upper speed): Al peak {r['refined_alu_peak_mpa']:.4f} MPa vs {r['fine_alu_peak_mpa']:.4f} MPa on 13 mm ({r['change_percent']:+.3f}%); displacement {r['refined_displacement_um']:.4f} um.")
 L.extend(['','### Similarity check (new / archived ratio vs exact geometric-similarity prediction)','','| Link | Quantity | Ratio | Predicted | Relative error |','|---:|:---|---:|---:|---:|'])
 for s in out['similarity_new_over_archived']:
  for c in s['checks']:L.append(f"| {s['distance_m']:g} | {c['quantity']} | {c['ratio']:.6f} | {c['predicted']:.6f} | {c.get('relative_error',c['ratio']/c['predicted']-1):+.2e} |")
 L.extend(['','Predictions: centrifugal stress s^2 w^2, centrifugal displacement s^3 w^2, angular-acceleration stress s^2 alpha, displacement s^3 alpha, gravity stress s, mass s^3, inertia s^5; frequencies 1/s are exact only without prestress (prestress raises them by a speed-dependent amount).',''])
 p=R/f'three_link_designs_{TAG}/RESULTS.md';text=p.read_text(encoding='utf-8') if p.exists() else ''
 text=text.split(MARK)[0].rstrip()+'\n\n'+'\n'.join(L)+'\n';p.write_text(text,encoding='utf-8')
def main():
 out={}
 for name,S in SETS.items():
  comp=rd(S['steel']/'compiled.json');mode=rd(S['steel']/'modal_response_h0.013.json');asm=rd(S['steel']/'assembly_screen.json');frozen=rd(S['steel']/'frozen_designs.json')
  wcmp=rd(S['w']/'comparison.json');wmodal=rd(S['w']/'modal_response_h0.013.json');field=rd(S['w']/'field_comparison.json')['rows'];wref=rd(S['w']/'refinement_comparison.json')
  rows=[]
  for i,x in enumerate(comp,1):
   ch=frozen['channels'][i-1];src=ch['source_designs'][0];fc=ch['config']['carrier_hz'];f,c=x['fine'],x['coarse']
   wf=next(r for r in wcmp if r['design']==i and r['mesh']==.013);wc=next(r for r in wcmp if r['design']==i and r['mesh']==.018)
   m=modal(mode,i);wm=modal(wmodal,i)
   rows.append(dict(distance_m=x['distance_m'],carrier_hz=fc,scale=src['scale'],omega_max_rad_s=math.pi*(fc+S['half']),alpha_max_rad_s2=src['peak_torque_nm']/src['inertia_kg_m2'],
    cad_mass_kg=src['mass_kg'],cad_inertia_kg_m2=src['inertia_kg_m2'],mesh_mass_kg_fine=f['mesh_mass_kg'],mesh_inertia_kg_m2_fine=f['mesh_inertia_kg_m2'],peak_torque_nm=src['peak_torque_nm'],
    steel=dict(centrifugal_alu_peak_mpa=f['centrifugal_raw_alu_vm_mpa'],centrifugal_alu_peak_coarse_mpa=c['centrifugal_raw_alu_vm_mpa'],horizontal_combined_alu_bound_mpa=f['horizontal_conservative_alu_vm_mpa'],
     horizontal_combined_u_bound_um=f['horizontal_conservative_u_um'],centrifugal_u_um=f['centrifugal_max_u_um'],all_attitude_alu_bound_mpa=f['combined_conservative_alu_vm_mpa'],all_attitude_u_bound_um=f['combined_conservative_u_um'],
     all_attitude_insert_bound_mpa=f['combined_conservative_steel_vm_mpa'],angular_only_alu_mpa=f['angular_only_alu_vm_mpa'],angular_only_u_um=f['angular_only_max_u_um'],horizontal_gravity_alu_bound_mpa=f['horizontal_gravity_alu_vm_bound_mpa'],
     phase_sampled_alu_bound_mpa=f['sampled_transition_gravity_bound_vm_mpa'],phase_sampled_u_bound_um=f['sampled_transition_gravity_bound_u_um'],
     regional_10mm_fine_mpa=f['regional_10mm_scaled_vm_mpa'],regional_10mm_coarse_mpa=c['regional_10mm_scaled_vm_mpa'],
     raw_peak_change_percent=x['raw_peak_change_percent'],displacement_change_percent=x['displacement_change_percent'],regional_change_percent=x['regional_change_percent'],
     modes=m,torsional_period_s=1/m['torsional_hz'],first_mode_period_s=1/m['center_first3_hz'][0],transition_s=S['T'],transition_over_torsional_period=S['T']*m['torsional_hz'],transition_over_first_period=S['T']*m['center_first3_hz'][0],
     insert_centrifugal_force_kn=asm[i-1]['max_insert_centrifugal_force_n']/1e3,series_shaft_carrier_torsion_hz=x['series_shaft_carrier_torsion_screen_hz'],shaft_only_torsion_hz=asm[i-1]['shaft_only_rotor_torsion_hz']),
    tungsten=dict(horizontal_combined_alu_bound_mpa=wf['tungsten']['horizontal_conservative_alu_vm_mpa'],horizontal_combined_u_bound_um=wf['tungsten']['horizontal_conservative_u_um'],
     steel_horizontal_alu_bound_mpa=wf['steel']['horizontal_conservative_alu_vm_mpa'],steel_horizontal_u_bound_um=wf['steel']['horizontal_conservative_u_um'],
     all_attitude_insert_bound_steel_mpa=wf['steel']['combined_conservative_steel_vm_mpa'],all_attitude_insert_bound_tungsten_mpa=wf['tungsten']['combined_conservative_tungsten_vm_mpa'],
     centrifugal_alu_peak_coarse_mpa=wc['tungsten']['centrifugal_raw_alu_vm_mpa'],centrifugal_alu_peak_fine_mpa=wf['tungsten']['centrifugal_raw_alu_vm_mpa'],
     displacement_change_percent=100*(wf['tungsten']['centrifugal_max_u_um']/wc['tungsten']['centrifugal_max_u_um']-1),regional_change_percent=100*(wf['tungsten']['regional_10mm_scaled_vm_mpa']/wc['tungsten']['regional_10mm_scaled_vm_mpa']-1),
     modes=wm,steel_insert_length_mm=STEEL_INSERT_H0_MM*src['scale'],tungsten_insert_length_mm=STEEL_INSERT_H0_MM*src['scale']*7850/18000,
     field=field[i-1])))
  out[name]=dict(rows=rows,tungsten_refinement=wref)
 sim=[]
 for a,b in zip(out['archived']['rows'],out['hop']['rows']):
  rs=b['scale']/a['scale'];rw=b['omega_max_rad_s']/a['omega_max_rad_s'];ra=b['alpha_max_rad_s2']/a['alpha_max_rad_s2']
  def chk(key,pred,grp='steel'):return dict(quantity=f'{grp}.{key}',ratio=b[grp][key]/a[grp][key],predicted=pred,relative_error=b[grp][key]/a[grp][key]/pred-1)
  sim.append(dict(distance_m=a['distance_m'],scale_ratio=rs,omega_ratio=rw,alpha_ratio=ra,checks=[chk('centrifugal_alu_peak_mpa',rs**2*rw**2),chk('centrifugal_u_um',rs**3*rw**2),chk('angular_only_alu_mpa',rs**2*ra),chk('angular_only_u_um',rs**3*ra),chk('horizontal_gravity_alu_bound_mpa',rs),
   dict(quantity='steel.modes.torsional_hz',ratio=b['steel']['modes']['torsional_hz']/a['steel']['modes']['torsional_hz'],predicted=1/rs,note='prestress makes this approximate'),
   dict(quantity='mass',ratio=b['cad_mass_kg']/a['cad_mass_kg'],predicted=rs**3),dict(quantity='inertia',ratio=b['cad_inertia_kg_m2']/a['cad_inertia_kg_m2'],predicted=rs**5)]))
 out['similarity_new_over_archived']=sim
 (R/f'three_link_designs_{TAG}/hop_vs_archived_summary.json').write_text(json.dumps(out,indent=2)+'\n')
 write_markdown(out)
 print(json.dumps(out,indent=1))
if __name__=='__main__':main()
